--
-- Table structure for table `adverse_instance_reporting`
--

DROP TABLE IF EXISTS `adverse_instance_reporting`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `adverse_instance_reporting` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `incident_date` date NOT NULL,
  `reporting_date` date DEFAULT NULL,
  `incident_nature` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `staff_involved` varchar(180) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `incident_details` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `injury_hazard` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `corrective_action` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `preventive_action` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `matter_resolved` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reported_to` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=102 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

