--
-- Table structure for table `cobaspure`
--

DROP TABLE IF EXISTS `cobaspure`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cobaspure` (
  `id` int NOT NULL AUTO_INCREMENT,
  `chemistry` varchar(45) NOT NULL DEFAULT 'No',
  `immunoassay` varchar(45) NOT NULL DEFAULT 'No',
  `consumablech` varchar(45) NOT NULL DEFAULT 'No',
  `consumableimm` varchar(45) NOT NULL DEFAULT 'No',
  `chimm` varchar(45) NOT NULL DEFAULT 'No',
  `cleandust` varchar(45) NOT NULL DEFAULT 'No',
  `waterplant` varchar(225) NOT NULL DEFAULT 'No',
  `boardreagent` varchar(225) NOT NULL DEFAULT 'No',
  `tds` varchar(225) NOT NULL,
  `conductivity` varchar(225) NOT NULL,
  `datetime` varchar(225) NOT NULL,
  `datetimess` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `username` varchar(225) NOT NULL,
  `timerec` varchar(45) NOT NULL,
  `one` mediumtext NOT NULL,
  `two` tinytext NOT NULL,
  `three` tinytext NOT NULL,
  `four` varchar(45) NOT NULL,
  `five` tinytext NOT NULL,
  `six` mediumtext NOT NULL,
  `seven` varchar(45) NOT NULL,
  `eight` text NOT NULL,
  `nine` mediumtext NOT NULL,
  `ten` tinytext NOT NULL,
  `eleven` tinytext NOT NULL,
  `twelve` tinytext NOT NULL,
  `thirteen` tinytext NOT NULL,
  `fourteen` varchar(45) NOT NULL,
  `fifteen` varchar(45) NOT NULL,
  `sixteen` text NOT NULL,
  `seventeen` varchar(45) NOT NULL,
  `eighteen` varchar(225) NOT NULL,
  `nineteen` varchar(225) NOT NULL,
  `twenty` mediumtext NOT NULL,
  `lampremaining` text NOT NULL,
  `cellremaining` text NOT NULL,
  `twentyone` mediumtext NOT NULL,
  `twentytwo` tinytext NOT NULL,
  `twentythree` text NOT NULL,
  `twentyfour` varchar(225) NOT NULL,
  `verifiedby` varchar(225) NOT NULL,
  `status` int NOT NULL,
  `variftime` varchar(225) NOT NULL,
  `submitform` int NOT NULL,
  `formfill` int NOT NULL DEFAULT '0',
  `rerun` varchar(225) NOT NULL,
  `timeentry` varchar(225) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4526 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

