--
-- Table structure for table `form_intimation_log`
--

DROP TABLE IF EXISTS `form_intimation_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `form_intimation_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `slot_date` date NOT NULL,
  `machine_key` varchar(64) NOT NULL,
  `slot_code` varchar(64) NOT NULL,
  `deadline_at` datetime NOT NULL,
  `sent_success` tinyint(1) NOT NULL DEFAULT '0',
  `message_text` text,
  `api_response` text,
  `error_text` text,
  `sent_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_slot_date_machine_slot` (`slot_date`,`machine_key`,`slot_code`)
) ENGINE=InnoDB AUTO_INCREMENT=3486 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

