DROP TABLE IF EXISTS `lifotronic_h100_weekly`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lifotronic_h100_weekly` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `hp_pump_cleaning` varchar(5) NOT NULL DEFAULT '',
  `diluting_tank_cleaning` varchar(5) NOT NULL DEFAULT '',
  `probe_inner_well` varchar(5) NOT NULL DEFAULT '',
  `probe_outer_well` varchar(5) NOT NULL DEFAULT '',
  `clean_system` varchar(5) NOT NULL DEFAULT '',
  `clean_sample_rack` varchar(5) NOT NULL DEFAULT '',
  `clean_sample_holder` varchar(5) NOT NULL DEFAULT '',
  `documentedby` varchar(120) NOT NULL,
  `approvedby` varchar(120) NOT NULL DEFAULT 'Pending',
  `datetime` varchar(30) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` varchar(1) NOT NULL DEFAULT '0',
  `verifiedby` varchar(120) DEFAULT NULL,
  `variftime` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_lifotronic_weekly_created_at` (`created_at`),
  KEY `idx_lifotronic_weekly_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=89 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
